// Focused acceptance through the actual Shell, profile, Host Remote and native composer.
const assert = require('node:assert/strict')
const { mkdirSync, writeFileSync, readFileSync, readdirSync, rmSync } = require('node:fs')
const { join } = require('node:path')

function install(root, name, label) {
  const directory = join(root, name)
  mkdirSync(directory, { recursive: true })
  writeFileSync(join(directory, 'SKILL.md'), `---\nname: ${name}\ndescription: Desktop acceptance fixture\n---\nInstructions for acceptance only.\n`)
  writeFileSync(join(directory, 'ui.json'), JSON.stringify({ displayName: label, shortDescription: '本机临时验收技能' }))
  return directory
}
exports.prepare = output => install(join(output, 'agents', 'skills'), 'smoke-shared', '共享验收技能')

exports.run = async ({ harness, output, until, save }) => {
  const js = source => harness.executeJavaScript(source)
  const workspacePath = join(output, '技能验收工作区')
  mkdirSync(workspacePath, { recursive: true })
  const workspace = await js(`fetch('/api/workspace/create', {method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({type:'client-request',rpcId:crypto.randomUUID(),method:'workspace/create',payload:{args:{request:{path:${JSON.stringify(workspacePath)}}}}})}).then(r=>r.json())`)
  assert.equal(workspace.result.ok, true, JSON.stringify(workspace))
  await until('workspace row', () => js(`!!document.querySelector('button[aria-label="在“技能验收工作区”中新建会话"]')`))
  await js(`document.querySelector('button[aria-label="在“技能验收工作区”中新建会话"]').click()`)
  await until('native composer', () => js(`!!document.querySelector('[contenteditable="true"]') && !!document.querySelector('[data-insight-skill-trigger]')`))
  // Wait for the new workspace's session history and composer to settle.
  await new Promise(resolve => setTimeout(resolve, 1500))
  await js(`document.querySelector('[data-insight-skill-trigger]').click()`)
  const expected = Object.keys(JSON.parse(readFileSync(join(process.env.INSIGHT_SMOKE_ROOT, 'build', 'skill-presentations.json'), 'utf8'))).length
  await until('generated platform skills', () => js(`document.querySelectorAll('[data-insight-skill-list] [role="option"]').length === ${expected}`), 20000)
  assert.equal(await js(`document.querySelector('[role="tab"][aria-selected="true"]').textContent`), '平台预置')
  const row = name => `[...document.querySelectorAll('[data-insight-skill-list] [role="option"]')].find(x=>x.id.endsWith('-'+${JSON.stringify(name)}))`
  const clickSkill = name => js(`${row(name)}.click()`)
  const callable = name => js(`${row(name)}?.getAttribute('aria-disabled') === 'false'`)
  const draft = () => js(`document.querySelector('[contenteditable="true"]').innerText`)
  await until('callable platform skill', () => callable('creator-recommendation'))
  await clickSkill('creator-recommendation')
  await until('platform native token', async () => (await draft()).includes('/creator-recommendation'))
  await js(`[...document.querySelectorAll('[role="tab"]')].find(x=>x.textContent==='用户自定义').click()`)
  await until('shared skill via Shell Remote', () => callable('smoke-shared'), 20000)
  await clickSkill('smoke-shared')
  await until('shared native token', async () => (await draft()).includes('/smoke-shared'))

  const appData = join(output, 'app-data')
  const relative = readdirSync(appData, { recursive: true }).find(path => /[/\\]accounts[/\\][a-f0-9]{32}[/\\]harness$/u.test(path))
  assert.ok(relative, 'Isolated current account DSH_HOME must exist')
  const account = install(join(appData, relative, 'skills'), 'smoke-account', '账号验收技能')
  await until('new account skill without restart', () => callable('smoke-account'), 20000)
  await clickSkill('smoke-account')
  await until('cross-tab selected count', () => js(`document.querySelector('[data-insight-skill-label]').textContent.includes('3')`))
  await until('account native token', async () => (await draft()).includes('/smoke-account'))
  await save('skill-tabs-user-selected', harness)
  assert.ok((await draft()).includes('/smoke-account'), 'Capturing the page must preserve the draft')
  writeFileSync(join(account, 'ui.json'), JSON.stringify({ displayName: '账号名称已更新' }))
  await until('sidecar update without restart', () => js(`${row('smoke-account')}?.textContent.includes('账号名称已更新')`), 10000)
  assert.ok((await draft()).includes('/smoke-account'), 'Sidecar changes must preserve the draft')
  writeFileSync(join(account, 'SKILL.md'), '---\nname: [unfinished\n')
  await until('partial update disabled', () => js(`${row('smoke-account')}?.getAttribute('aria-disabled') === 'true'`), 10000)
  assert.ok((await draft()).includes('/smoke-account'), 'Partial writes must preserve the draft')
  install(join(appData, relative, 'skills'), 'smoke-account', '恢复后的账号技能')
  await until('recovered skill', () => callable('smoke-account'), 20000)
  assert.ok((await draft()).includes('/smoke-account'), 'Recovery must preserve the draft')
  rmSync(account, { recursive: true })
  await until('confirmed removal', () => js(`!${row('smoke-account')}`), 10000)
  assert.ok((await draft()).includes('/smoke-account'), 'Removal must preserve the user draft')
  assert.equal(await js(`document.querySelector('[data-insight-skill-label]').textContent.includes('2')`), true)
  await save('skill-tabs-removed', harness)
  const search = `document.querySelector('[data-insight-skill-panel] input')`
  await js(`Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(${search},'共享'); ${search}.dispatchEvent(new Event('input',{bubbles:true}))`)
  await until('scoped user search', () => js(`document.querySelectorAll('[data-insight-skill-list] [role="option"]').length === 1 && !!${row('smoke-shared')}`))
  // Native key events also exercise Escape and the reopen default.
  harness.sendInputEvent({ type: 'keyDown', keyCode: 'ESC' })
  harness.sendInputEvent({ type: 'keyUp', keyCode: 'ESC' })
  await until('closed picker', () => js(`!document.querySelector('[data-insight-skill-panel]')`))
  await js(`document.querySelector('[data-insight-skill-trigger]').click()`)
  await until('reopened platform tab', () => js(`document.querySelector('[role="tab"][aria-selected="true"]')?.textContent==='平台预置'`))
  assert.equal(await js(`${search}.value`), '')
  await save('skill-tabs-platform', harness)
  writeFileSync(join(output, 'skill-tabs-passed'), 'Actual Shell: platform/user tabs, global roots, native draft, install/update/partial-write/recovery/removal, reopen default passed. No model request sent.\n')
  console.log('CANDIDATE_SKILL_TABS_PASSED')
}
